function refreshScrollSpy(){
  const path=activeRoute();
  if(path.startsWith('/cars/')){setNavActive('cars');return;}
  if(path!=='/')return;
  const sections=[
    {key:'home-hero',els:[document.querySelector('#home-hero')]},
    {key:'sell-form',els:[document.querySelector('.home-form-section'),document.querySelector('#sell-band'),document.querySelector('#sell-process')]},
    {key:'cars',els:[document.querySelector('#cars')]},
    {key:'about',els:[document.querySelector('#about')]},
    {key:'contact',els:[document.querySelector('#contact'),document.querySelector('#sell-cta')]}
  ].map(item=>({...item,els:item.els.filter(Boolean)})).filter(item=>item.els.length);
  if(!sections.length)return;
  const line=(document.querySelector('.site-header')?.getBoundingClientRect().bottom||0)+40;
  let active=sections.find(item=>item.els.some(el=>{const rect=el.getBoundingClientRect();return rect.top<=line&&rect.bottom>line;}));
  if(!active)active=sections.reduce((nearest,item)=>Math.min(...item.els.map(el=>Math.abs(el.getBoundingClientRect().top-line)))<Math.min(...nearest.els.map(el=>Math.abs(el.getBoundingClientRect().top-line)))?item:nearest,sections[0]);
  setNavActive(active.key);
}
function initScrollSpy(){refreshScrollSpy();}
function initMotionControls() {
  document.querySelector('.back-to-top')?.addEventListener('click',()=>window.scrollTo({top:0,behavior:'smooth'}));
  updateScrollMotion();
  const cursor=document.querySelector('.custom-cursor');if(cursor&&!cursor.dataset.bound){cursor.dataset.bound='true';document.addEventListener('pointermove',event=>{cursor.style.transform=`translate3d(${event.clientX}px,${event.clientY}px,0) translate(-50%,-50%)`;},{passive:true});document.addEventListener('pointerover',event=>{const target=event.target.closest('.button,.car-card,.how-card');if(!target)return;const label=target.textContent.toLowerCase();cursor.querySelector('span').textContent=target.matches('.car-card,.how-card')||/browse|explore|available|contact|call/.test(label)?'View':'Sell';cursor.classList.add('is-active');document.body.classList.add('cursor-active');});document.addEventListener('pointerout',event=>{if(event.target.closest('.button,.car-card,.how-card')&&!event.relatedTarget?.closest('.button,.car-card,.how-card')){cursor.classList.remove('is-active');document.body.classList.remove('cursor-active');}});}
}
function formToLead(form,type) {
  const fd=new FormData(form);
  return {inquiryType:type,customerName:String(fd.get('customerName')||'').trim(),mobile:String(fd.get('mobile')||'').replace(/\D/g,''),carMakeModel:String(fd.get('carMakeModel')||'').trim(),year:String(fd.get('year')||'').trim(),kilometres:String(fd.get('kilometres')||'').trim(),variant:String(fd.get('variant')||'').trim(),fuelType:String(fd.get('fuelType')||'').trim(),transmission:String(fd.get('transmission')||'').trim(),conditionNotes:String(fd.get('conditionNotes')||'').trim(),consent:fd.get('consent')==='on',website:String(fd.get('website')||''),sourcePage:location.pathname,vehicleSlug:form.dataset.car||'',vehicleName:form.dataset.car?(()=>{const c=DEMO_CARS.find(x=>x.slug===form.dataset.car);return c?`${c.make} ${c.model}`:''})():''};
}
async function sendLead(form,type,errorId,statusId,button) {
  const errorEl=document.getElementById(errorId), statusEl=document.getElementById(statusId);errorEl.textContent='';statusEl.hidden=true;
  if(!form.reportValidity())return;
  const lead=formToLead(form,type);
  if(lead.website)return;
  button.disabled=true;button.dataset.original=button.innerHTML;button.innerHTML='Sending…';
  try {
    const response=await fetch('/api/enquiries',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(lead)});
    const result=await response.json();
    if(!response.ok||result.ok!==true||!result.leadId)throw new Error(result.error||'The enquiry could not be confirmed. Please call the showroom.');
    window.__lastLeadId=result.leadId;
    if(type==='SELL')navigate('/thanks?success=1');else{statusEl.className='form-status success';statusEl.textContent=`Enquiry received. Reference ${result.leadId}. The M24 team will contact you.`;statusEl.hidden=false;form.reset();}
  } catch(error) {statusEl.className='form-status error';statusEl.textContent=error.message||'Could not send the enquiry. Please retry or contact the showroom.';statusEl.hidden=false;}
  finally {button.disabled=false;button.innerHTML=button.dataset.original;}
}
function submitSellForm(event){event.preventDefault();sendLead(event.currentTarget,'SELL','sell-error','sell-status',event.currentTarget.querySelector('button[type="submit"]'));}
function submitEnquiryForm(event){event.preventDefault();sendLead(event.currentTarget,event.currentTarget.dataset.type,'enquiry-error','enquiry-status',event.currentTarget.querySelector('button[type="submit"]'));}
render();
